// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));
        vm.assume(caller != newOwner);

        // Impersonate admin (the contract deployer) to call setOwner
        address admin = address(this);
        vm.prank(admin);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // If call succeeded, owner should be newOwner, not caller
        if (success) {
            address actualOwner = c.owner();
            assertTrue(actualOwner == newOwner, "Owner should equal passed argument");
        }
    }
}

